            conn.execute("ROLLBACK")
            raise ValueError("payment exceeds outstanding amount")
        conn.execute(
            "UPDATE orders SET paid_cents = paid_cents + ?, status = CASE WHEN paid_cents + ? >= amount_cents THEN 'settled' ELSE 'accepted' END WHERE tenant=? AND order_id=?",
            (amount_cents, amount_cents, tenant, order_id),
        )
        # 余额变动与流水留痕同一事务：流水之和始终可以解释 paid_cents。
        conn.execute(
            "INSERT INTO order_ledger(tenant, order_id, kind, amount_cents) VALUES(?,?, 'payment', ?)",
            (tenant, order_id, amount_cents),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, order_id)

def add_refund(tenant: str, order_id: str, refund_id: str, amount_cents: int) -> dict | None:
    """登记冲正。订单不存在返回 None；超过当前已收金额抛 RefundExceedsPaid。

    同一（租户, 订单, 冲正标识）重复请求不重复生效，返回首次执行结果。
    """
    if amount_cents <= 0:
        raise ValueError("refund amount must be positive")
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        # 幂等放最前：重复请求直接回放首次结果，不再做余额判断。
        existing = conn.execute(
            "SELECT amount_cents, created_at FROM order_ledger "
            "WHERE tenant=? AND order_id=? AND kind='refund' AND ref_id=?",
            (tenant, order_id, refund_id),
        ).fetchone()
        if existing is not None:
            conn.execute("COMMIT")
            result = _refund_result(tenant, order_id, refund_id, existing["created_at"])
            if result is not None:
                result["idempotent_replay"] = True
            return result
        if amount_cents > row["paid_cents"]:
            conn.execute("ROLLBACK")
            raise RefundExceedsPaid("refund exceeds paid amount")
        conn.execute(
            "UPDATE orders SET paid_cents = paid_cents - ?, status = CASE WHEN paid_cents - ? >= amount_cents THEN 'settled' ELSE 'accepted' END WHERE tenant=? AND order_id=?",
            (amount_cents, amount_cents, tenant, order_id),
        )
        conn.execute(
            "INSERT INTO order_ledger(tenant, order_id, kind, amount_cents, ref_id) VALUES(?,?, 'refund', ?,?)",
            (tenant, order_id, amount_cents, refund_id),
        )
        created_row = conn.execute(
            "SELECT created_at FROM order_ledger WHERE tenant=? AND order_id=? AND kind='refund' AND ref_id=?",
            (tenant, order_id, refund_id),
        ).fetchone()
        conn.execute("COMMIT")
    finally:
        conn.close()
    result = _refund_result(tenant, order_id, refund_id, created_row["created_at"])
    if result is not None:
        result["idempotent_replay"] = False
    return result

def _refund_result(tenant: str, order_id: str, refund_id: str, created_at: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if row is None:
            return None
        return {
            "order_id": order_id,
            "refund_id": refund_id,
            "amount_cents": _refund_amount(conn, tenant, order_id, refund_id),
            "paid_cents": row["paid_cents"],
            "outstanding_cents": row["amount_cents"] - row["paid_cents"],
            "created_at": created_at,
        }
    finally:
        conn.close()

def _refund_amount(conn: sqlite3.Connection, tenant: str, order_id: str, refund_id: str) -> int:
    row = conn.execute(
        "SELECT amount_cents FROM order_ledger WHERE tenant=? AND order_id=? AND kind='refund' AND ref_id=?",
        (tenant, order_id, refund_id),
    ).fetchone()
    return row["amount_cents"]

